#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0
# Copyright 2026 Tom F. <tomf@tomtomtech.net> (https://github.com/tomtom215)
#
# Asserts that the numbers quoted in `book/src/reference/benchmarks.md` prose
# still agree with the measurement tables on the same page.
#
# Why this exists. The page is generated by
# `benches/scripts/generate_book_page.sh`: the tables are emitted from
# criterion's estimates.json, the prose was typed by hand into a quoted
# heredoc. So the tables regenerated on every bench run and the prose did not.
# Between v0.5.0 and v0.8.0 the page simultaneously stated:
#
#   prose : "the ~1.4ms HTTP round-trip dominates"
#   table : transport_payload_scaling/jsonrpc_send/64 = 189.9 µs
#
#   prose : "connection reuse saves ~140µs (9%)"
#   table : 312.5 µs new client vs 189.0 µs reused  ->  123.5 µs, 39.5%
#
# The second understated connection reuse by more than 4x, in a document whose
# whole job is to be quotable. This is the same failure the file-length ratchet
# was built to cure, and its header already names the rule: a number nothing
# recomputes is a number that decays.
#
# The generator now interpolates both paragraphs from the same estimates the
# tables come from, so a fresh `cargo bench` + regenerate keeps them true. This
# script is the ratchet for the gap that fix cannot close: the page is a
# committed artifact, editable by hand, and regenerated only when someone runs
# the benchmarks. It re-derives the quoted values from the committed tables and
# fails if the prose has drifted from them.
#
# Deliberately narrow. It checks the two claims that actually decayed, by name.
# A generic "find every number in the prose" heuristic would flag version
# strings, section headings and payload sizes, and a gate that cries wolf gets
# routed around. New quoted measurements should be added here explicitly.
#
# Usage:
#   ./scripts/check_benchmark_prose.sh
#
# Exit codes:
#   0  prose agrees with the tables
#   1  prose has drifted, or a table row the prose depends on is missing

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
PAGE="$REPO_ROOT/book/src/reference/benchmarks.md"

if [ ! -f "$PAGE" ]; then
    echo "check_benchmark_prose: $PAGE not found" >&2
    exit 1
fi

python3 - "$PAGE" <<'PY'
import re
import sys

page = sys.argv[1]
text = open(page, encoding="utf-8").read()

UNITS = {"ns": 1.0, "µs": 1_000.0, "us": 1_000.0, "ms": 1_000_000.0}

def table_ns(row):
    """Median for a table row, in nanoseconds.

    Rows look like: | `transport_payload_scaling/jsonrpc_send/64` | 189.9 µs |
    """
    pattern = r"\|\s*`" + re.escape(row) + r"`\s*\|\s*([0-9.]+)\s*(ns|µs|us|ms)\s*\|"
    m = re.search(pattern, text)
    if not m:
        print(f"  MISSING TABLE ROW  {row}")
        print("    the prose quotes this measurement but no table row supplies it")
        return None
    return float(m.group(1)) * UNITS[m.group(2)]

def fmt(ns):
    """Render like generate_book_page.sh's extract_median."""
    if ns >= 1_000_000:
        return f"{ns / 1_000_000:.2f} ms"
    if ns >= 1_000:
        return f"{ns / 1_000:.1f} µs"
    return f"{ns:.0f} ns"

failures = []
missing = False

# ── Claim 1: transport payload insensitivity ─────────────────────────────
small = table_ns("transport_payload_scaling/jsonrpc_send/64")
large = table_ns("transport_payload_scaling/jsonrpc_send/16384")
if small is None or large is None:
    missing = True
else:
    pct = f"{((large - small) / small) * 100:.1f}%"
    baseline = fmt(small)
    for want, label in ((pct, "64B->16KB latency increase"),
                        (baseline, "HTTP round-trip baseline")):
        if want not in text:
            failures.append(
                f"prose does not contain {want!r} ({label}); "
                f"recomputed from the tables on this page"
            )

# ── Claim 2: connection reuse impact ─────────────────────────────────────
new_client = table_ns("realistic_connection/new_client_per_request")
reused = table_ns("realistic_connection/reused_client")
if new_client is None or reused is None:
    missing = True
else:
    saved = new_client - reused
    saving = (
        f"{saved / 1_000:.1f} µs" if saved >= 1_000 else f"{saved:.0f} ns"
    )
    pct = f"{(saved / new_client) * 100:.1f}%"
    checks = (
        (f"{saving} ({pct})", "connection-reuse saving"),
        (fmt(new_client), "new-client-per-request cost"),
        (fmt(reused), "reused-client cost"),
    )
    for want, label in checks:
        if want not in text:
            failures.append(
                f"prose does not contain {want!r} ({label}); "
                f"recomputed from the tables on this page"
            )

if missing or failures:
    print("check_benchmark_prose: benchmarks.md prose disagrees with its own tables")
    for f in failures:
        print(f"  DRIFT  {f}")
    print()
    print("  The prose on this page quotes measurements. Regenerate it with")
    print("    cargo bench -p a2a-benchmarks && ./benches/scripts/generate_book_page.sh")
    print("  rather than editing the numbers by hand.")
    sys.exit(1)

print("check_benchmark_prose: 5 quoted value(s) agree with the tables on the page")
PY
